"""Intent tests for mdata.validate_rows (PL-01 step 2): DATA-02, TC-01."""

from __future__ import annotations

import pytest

from mdata import RawRow
from mdata.validate import validate_rows


def _rows(triples: list[list]) -> list[RawRow]:
    return [RawRow(date=date, ticker=ticker, close=close) for date, ticker, close in triples]


def _sample_rows(contract_sample) -> list[RawRow]:
    return [RawRow(**row) for row in contract_sample("mdata.RawRow")["rows"]]


@pytest.mark.intent
def test_tc01_drops_unusable_rows_keeps_later_duplicate_and_sorts(golden):
    given, expected = golden("mdata", "TC-01")
    result = validate_rows(_rows(given["rows"]), given["tickers"])
    assert result == _rows(expected["rows"])


@pytest.mark.intent
def test_tc01_returns_a_list_of_rawrows(golden):
    given, _ = golden("mdata", "TC-01")
    result = validate_rows(_rows(given["rows"]))
    assert isinstance(result, list)
    assert all(isinstance(row, RawRow) for row in result)


@pytest.mark.intent
def test_reversed_sample_comes_back_sorted_by_date_then_ticker(contract_sample):
    rows = _sample_rows(contract_sample)
    result = validate_rows(list(reversed(rows)))
    keys = [(row.date, row.ticker) for row in result]
    assert keys == sorted(keys)
    assert len(result) == len(rows) - 1
    assert all(row.close is not None and row.close > 0 for row in result)


@pytest.mark.intent
def test_requested_ticker_absent_from_rows_is_a_keyerror_naming_it(contract_sample):
    rows = _sample_rows(contract_sample)
    with pytest.raises(KeyError, match="NVDA"):
        validate_rows(rows, ["AAPL", "NVDA"])


@pytest.mark.intent
def test_requested_ticker_with_only_unusable_rows_is_a_keyerror_naming_it(contract_sample):
    rows = [
        row
        for row in _sample_rows(contract_sample)
        if row.ticker == "AAPL" or row.close is None
    ]
    with pytest.raises(KeyError, match="MSFT"):
        validate_rows(rows, ["AAPL", "MSFT"])


@pytest.mark.intent
def test_tc01_ticker_whose_rows_are_all_dropped_is_a_keyerror(golden):
    given, _ = golden("mdata", "TC-01")
    rows = [row for row in _rows(given["rows"]) if row.ticker != "B" or (row.close or 0) <= 0]
    with pytest.raises(KeyError, match="B"):
        validate_rows(rows, ["A", "B"])

